import { useCallback, useMemo, useState } from 'react';
import { useRecoilValue } from 'recoil';
import { userInformationAtom } from '../../../../Services/_states/auth.js';
import { useSnackBar } from '../../../../components/FlowBuilder/Common/SnackBar/index.tsx';
import { RECORD_COPY } from '../constants/recordCopy';
import { recordTemplateSummaryService } from '../services/recordTemplateSummaryService';
import {
  getSummaryDate,
  getTemplateDetailPayloadKeys,
} from '../utils/statusLogUtils';

const EMPTY_TEMPLATE = {
  name: '',
  id: '',
  data: null,
  sentDate: '',
  sourceStatus: null,
};

function normalizeDate(value) {
  if (!value) {
    return '';
  }

  const text = String(value).trim();

  if (!text) {
    return '';
  }

  if (text.includes('T')) {
    return text.split('T')[0];
  }

  if (text.includes(' ')) {
    return text.split(' ')[0];
  }

  if (/^\d{2}-\d{2}-\d{4}$/.test(text)) {
    const [day, month, year] = text.split('-');

    return `${year}-${month}-${day}`;
  }

  if (/^\d{4}-\d{2}-\d{2}$/.test(text)) {
    return text;
  }

  return text;
}

export default function useStatusLogTemplate() {
  const { showSnackBar } = useSnackBar();

  const loggedInUser = useRecoilValue(userInformationAtom);

  const companyId =
    loggedInUser?.profile?.organisation?.organisation_id || '';

  const [selectedTemplate, setSelectedTemplate] = useState(null);
  const [templateTab, setTemplateTab] = useState('details');
  const [templateDateSummary, setTemplateDateSummary] = useState([]);
  const [templateUsers, setTemplateUsers] = useState([]);
  const [templateUsersTotal, setTemplateUsersTotal] = useState(0);
  const [selectedTemplateDate, setSelectedTemplateDate] = useState('');
  const [templateStartDate, setTemplateStartDate] = useState('');
  const [templateEndDate, setTemplateEndDate] = useState('');
  const [isTemplateLoading, setIsTemplateLoading] = useState(false);
  const [isUsersLoading, setIsUsersLoading] = useState(false);

  const resetTemplateState = useCallback(() => {
    setSelectedTemplate(null);
    setTemplateTab('details');
    setTemplateDateSummary([]);
    setTemplateUsers([]);
    setTemplateUsersTotal(0);
    setSelectedTemplateDate('');
    setTemplateStartDate('');
    setTemplateEndDate('');
    setIsTemplateLoading(false);
    setIsUsersLoading(false);
  }, []);

  const fetchDateSummary = useCallback(
    async (
      templateId,
      startDate = '',
      endDate = ''
    ) => {
      if (!templateId || !companyId) {
        setTemplateDateSummary([]);
        return [];
      }

      setIsTemplateLoading(true);

      try {
        const data =
          await recordTemplateSummaryService.getDateWiseSummary(
            templateId,
            {
              companyId,
              startDate: normalizeDate(startDate),
              endDate: normalizeDate(endDate),
            }
          );

        setTemplateDateSummary(data || []);

        return data || [];
      } catch (error) {
        console.error(
          'Status Logs - Date Summary Error:',
          error
        );

        setTemplateDateSummary([]);

        showSnackBar(
          error?.message ||
            RECORD_COPY.statusLogs.template.loadDatesError,
          'error'
        );

        return [];
      } finally {
        setIsTemplateLoading(false);
      }
    },
    [companyId, showSnackBar]
  );

  const fetchUsers = useCallback(
    async (templateId, date) => {
      if (!templateId || !date || !companyId) {
        setTemplateUsers([]);
        setTemplateUsersTotal(0);
        return;
      }

      setIsUsersLoading(true);

      try {
        const {
          users,
          total,
        } =
          await recordTemplateSummaryService.getUserSummary(
            templateId,
            normalizeDate(date),
            {
              companyId,
              page: 0,
              limit: 100,
              search: '',
              status: '',
            }
          );

        setTemplateUsers(users || []);

        setTemplateUsersTotal(
          Number(total) || 0
        );
      } catch (error) {
        console.error(
          'Status Logs - Users Error:',
          error
        );

        setTemplateUsers([]);
        setTemplateUsersTotal(0);

        showSnackBar(
          error?.message ||
            RECORD_COPY.statusLogs.template.loadUsersError,
          'error'
        );
      } finally {
        setIsUsersLoading(false);
      }
    },
    [companyId, showSnackBar]
  );

  const openTemplate = useCallback(
    async ({
      row,
      templateName,
      sentDate,
    }) => {
      if (!templateName) {
        return null;
      }

      const nextTemplate = {
        name: templateName,
        id: '',
        data: row?.template || row,
        sentDate:
          sentDate ||
          row?.updated_at ||
          row?.created_at ||
          '',
        sourceStatus: row,
      };

      setSelectedTemplate(nextTemplate);

      setTemplateTab('dates');

      setTemplateDateSummary([]);

      setTemplateUsers([]);

      setTemplateUsersTotal(0);

      setSelectedTemplateDate('');

      setTemplateStartDate('');

      setTemplateEndDate('');

      const templateId =
        await recordTemplateSummaryService.resolveTemplateId({
          row,
          templateName,
        });

      if (!templateId) {
        showSnackBar(
          RECORD_COPY.statusLogs.templateIdMissing(
            templateName
          ),
          'warning'
        );

        setSelectedTemplate((prev) =>
          prev
            ? {
                ...prev,
                id: '',
              }
            : prev
        );

        setTemplateTab('details');

        return null;
      }

      setSelectedTemplate((prev) =>
        prev
          ? {
              ...prev,
              id: templateId,
            }
          : prev
      );

      await fetchDateSummary(
        templateId,
        '',
        ''
      );

      return templateId;
    },
    [
      fetchDateSummary,
      showSnackBar,
    ]
  );

  const handleDateClick = useCallback(
    async (summaryRow) => {
      const templateId =
        selectedTemplate?.id;

      const date =
        getSummaryDate(summaryRow);

      if (!templateId) {
        showSnackBar(
          RECORD_COPY.statusLogs.template.idMissing,
          'warning'
        );

        return;
      }

      if (!date) {
        showSnackBar(
          RECORD_COPY.statusLogs.template.dateMissing,
          'warning'
        );

        return;
      }

      const normalizedDate =
        normalizeDate(date);

      setSelectedTemplateDate(
        normalizedDate
      );

      setTemplateTab('users');

      await fetchUsers(
        templateId,
        normalizedDate
      );
    },
    [
      fetchUsers,
      selectedTemplate?.id,
      showSnackBar,
    ]
  );

  const handleTabChange = useCallback(
    (nextTab) => {
      if (
        nextTab === 'users' &&
        !selectedTemplateDate
      ) {
        showSnackBar(
          RECORD_COPY.statusLogs.selectDateFirst,
          'warning'
        );

        setTemplateTab('dates');

        return;
      }

      setTemplateTab(nextTab);
    },
    [
      selectedTemplateDate,
      showSnackBar,
    ]
  );

  const handleDateRangeChange =
    useCallback(
      async ({
        startDate,
        endDate,
      }) => {
        const normalizedStartDate =
          normalizeDate(startDate);

        const normalizedEndDate =
          normalizeDate(endDate);

        setTemplateStartDate(
          normalizedStartDate
        );

        setTemplateEndDate(
          normalizedEndDate
        );

        if (!selectedTemplate?.id) {
          return;
        }

        await fetchDateSummary(
          selectedTemplate.id,
          normalizedStartDate,
          normalizedEndDate
        );
      },
      [
        fetchDateSummary,
        selectedTemplate?.id,
      ]
    );

  const clearDateRange =
    useCallback(
      async () => {
        setTemplateStartDate('');
        setTemplateEndDate('');

        if (!selectedTemplate?.id) {
          return;
        }

        await fetchDateSummary(
          selectedTemplate.id,
          '',
          ''
        );
      },
      [
        fetchDateSummary,
        selectedTemplate?.id,
      ]
    );

  const templateDetailKeys =
    useMemo(
      () =>
        getTemplateDetailPayloadKeys(
          selectedTemplate?.data || {}
        ),
      [selectedTemplate?.data]
    );

  return {
    selectedTemplate,
    templateTab,
    templateDateSummary,
    templateUsers,
    templateUsersTotal,
    selectedTemplateDate,
    templateStartDate,
    templateEndDate,
    isTemplateLoading,
    isUsersLoading,
    templateDetailKeys,
    openTemplate,
    resetTemplateState,
    handleDateClick,
    handleTabChange,
    setTemplateTab,
    handleDateRangeChange,
    clearDateRange,
    fetchDateSummary,
  };
}

export { EMPTY_TEMPLATE };