import React, { useMemo } from 'react';
import { Box, CircularProgress, TextField, Typography } from '@mui/material';
import dayjs from 'dayjs';
import { Button, DataTable, EmptyState, TableSkeleton } from '../../../../../../components/ui';
import { useFeatureTheme } from '../../../../../../theme/hooks/useFeatureTheme';
import useBusinessFunctionsTableSx from '../../../../hooks/useBusinessFunctionsTableSx';
import { buildTemplateDateTableColumns } from '../../../config/statusLogTableColumns';
import { RECORD_COPY } from '../../../constants/recordCopy';

export default function StatusLogTemplateDatesTable({
  rows = [],
  loading = false,
  startDate = '',
  endDate = '',
  isMobile = false,
  onStartDateChange,
  onEndDateChange,
  onClearRange,
  onDateClick,
}) {
  const { semantic, typography } = useFeatureTheme();
  const { tableOverrides } = useBusinessFunctionsTableSx();
  const copy = RECORD_COPY.statusLogs.template;

  const columns = useMemo(
    () => buildTemplateDateTableColumns({ onDateClick }),
    [onDateClick]
  );

  const tableMaxHeight = isMobile ? 'calc(100dvh - 380px)' : 'min(52vh, 460px)';

  return (
    <Box sx={{ minWidth: 0 }}>
      <Box
        sx={{
          mb: 2,
          p: 1.5,
          border: `1px solid ${semantic.borders.border}`,
          borderRadius: 2,
          bgcolor: semantic.surfaces.surfaceSubtle ?? semantic.surfaces.surface,
          display: 'flex',
          alignItems: { xs: 'stretch', sm: 'center' },
          flexDirection: { xs: 'column', sm: 'row' },
          gap: 1.5,
        }}
      >
        <Typography
          sx={{
            fontSize: typography.fontSizeSm,
            fontWeight: typography.fontWeightSemibold,
            color: semantic.text.primary,
          }}
        >
          {copy.filterDateRange}
        </Typography>

        <TextField
          label={copy.startDate}
          type="date"
          size="small"
          value={startDate}
          onChange={(event) => onStartDateChange?.(event.target.value, endDate)}
          InputLabelProps={{ shrink: true }}
          inputProps={{ max: dayjs().format('YYYY-MM-DD') }}
          sx={{ width: { xs: '100%', sm: 150 } }}
        />

        <TextField
          label={copy.endDate}
          type="date"
          size="small"
          value={endDate}
          disabled={!startDate}
          onChange={(event) => onEndDateChange?.(startDate, event.target.value)}
          InputLabelProps={{ shrink: true }}
          inputProps={{
            min: startDate || undefined,
            max: dayjs().format('YYYY-MM-DD'),
          }}
          sx={{ width: { xs: '100%', sm: 150 } }}
        />

        {(startDate || endDate) ? (
          <Button variant="outline" size="sm" onClick={onClearRange} sx={{ width: { xs: '100%', sm: 'auto' } }}>
            {copy.clearRange}
          </Button>
        ) : null}
      </Box>

      {loading ? (
        <Box sx={{ minHeight: 240, display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 1 }}>
          <CircularProgress size={24} />
          <Typography sx={{ fontSize: typography.fontSizeSm, color: semantic.text.secondary }}>
            {copy.loadingDates}
          </Typography>
        </Box>
      ) : rows.length === 0 ? (
        <EmptyState title={copy.noDates} description="" />
      ) : (
        <Box
          sx={{
            border: `1px solid ${semantic.borders.border}`,
            borderRadius: 2,
            overflow: 'hidden',
            minWidth: 0,
          }}
        >
          <DataTable
            columns={columns}
            data={rows}
            getRowId={(row, index) => String(row.id || row.sent_date || row.date || index)}
            enableStickyHeader
            layoutMode="grid"
            skeleton={<TableSkeleton rowCount={5} columnCount={columns.length} />}
            muiTableHeadCellProps={tableOverrides.muiTableHeadCellProps}
            muiTableBodyCellProps={tableOverrides.muiTableBodyCellProps}
            muiTableContainerProps={{
              sx: {
                maxHeight: tableMaxHeight,
                overflowX: 'auto',
                overflowY: 'auto',
                WebkitOverflowScrolling: 'touch',
              },
            }}
          />
        </Box>
      )}
    </Box>
  );
}
