import React from 'react';
import { Alert, Box, Typography } from '@mui/material';
import { Button } from '../../../../components/ui';
import { useFeatureTheme } from '../../../../theme/hooks/useFeatureTheme';
import LeanBulkSendPanel from '../../../whatsapp-templates/components/send/LeanBulkSendPanel';
import LeadSendTemplateBulkMappingPanel from './LeadSendTemplateBulkMappingPanel';
import LeadSendTemplatePreviewPanel from './LeadSendTemplatePreviewPanel';

export default function LeadSendTemplateBulkView({
  copy,
  styles,
  template,
  selectedCount,
  liveBodyParams = [],
  bulkMappingFields = [],
  columnOptions = [],
  coverage,
  gapLines = [],
  onColumnSelect,
  onQueueSelected,
  isQueueing = false,
  leanSend,
}) {
  const { semantic, typography } = useFeatureTheme();
  const noValidPhones = coverage?.phoneSummary?.withPhone === 0;

  return (
    <Box sx={styles?.leadSendTemplateSplitBody}>
      <Box sx={styles?.leadSendTemplateBulkSplitGrid ?? styles?.leadSendTemplateSplitGrid}>
        <Box sx={styles?.leadSendTemplateBulkMain}>
          <Box>
            <Typography
              sx={{
                fontSize: typography.fontSizeMd,
                fontWeight: typography.fontWeightSemibold,
                color: semantic.text.primary,
              }}
            >
              {copy.bulk.readyTitle(selectedCount)}
            </Typography>
            <Typography
              sx={{
                fontSize: typography.fontSizeSm,
                color: semantic.text.secondary,
                mt: 0.5,
                lineHeight: 1.5,
              }}
            >
              Map columns, then add the selected records to the queue. Messages start only after Send.
            </Typography>
          </Box>

          {noValidPhones ? (
            <Alert severity="error">{copy.direct.noPhoneWarning}</Alert>
          ) : null}

          <Box sx={styles?.leadSendTemplateBulkSection}>
            <LeadSendTemplateBulkMappingPanel
              copy={copy}
              styles={styles}
              mappingFields={bulkMappingFields}
              columnOptions={columnOptions}
              onColumnSelect={onColumnSelect}
            />
            <Button
              variant="outline"
              size="sm"
              loading={isQueueing}
              disabled={isQueueing || noValidPhones || Boolean(leanSend?.draft) || Boolean(leanSend?.job)}
              onClick={onQueueSelected}
              sx={{ mt: 1.5 }}
            >
              Queue selected leads
            </Button>
          </Box>

          {gapLines.length ? (
            <Alert severity="warning">
              <Box component="ul" sx={{ m: 0, pl: 2 }}>
                {gapLines.map((line) => (
                  <Box component="li" key={line.paramName} sx={{ fontSize: typography.fontSizeSm }}>
                    {copy.bulk.gapLine(line.label, line.missingCount, line.totalRows)}
                  </Box>
                ))}
              </Box>
            </Alert>
          ) : null}

          <LeanBulkSendPanel template={template} controller={leanSend} />
        </Box>

        <Box sx={styles?.leadSendTemplateSplitPreview}>
          <LeadSendTemplatePreviewPanel template={template} bodyParams={liveBodyParams} />
        </Box>
      </Box>
    </Box>
  );
}
