import React from 'react';
import {
  Avatar,
  Box,
  Button,
  IconButton,
  Tooltip,
  Typography,
} from '@mui/material';
import CloseIcon from '@mui/icons-material/Close';
import InfoOutlinedIcon from '@mui/icons-material/InfoOutlined';
import { LEAD_CHAT_COPY } from '../constants/leadChatCopy';
import {
  getConversationAvatarInitial,
  getConversationDisplayName,
  getConversationPhone,
  formatLastSeenLabel,
} from '../utils/leadChatIdentity';
import {
  canEndLeadChatSession,
  canShowSessionToggle,
  canStartLeadChatSession,
  getIntervenedAgentLabel,
  isChatLockedByOtherUser,
} from '../utils/leadChatSessionRules';
import { isComposerActive, isComposerLocked } from '../utils/leadChatComposerMode';
import useLeadChatSx from '../hooks/useLeadChatSx';

function HeaderStatusLine({ label, tooltip }) {
  const sx = useLeadChatSx();

  return (
    <Box sx={sx.headerStatusRow}>
      <Typography sx={sx.headerSubtitle} noWrap component="span">
        {label}
      </Typography>
      {tooltip ? (
        <Tooltip title={tooltip} arrow placement="bottom">
          <IconButton size="small" sx={sx.headerInfoButton} aria-label="Session info">
            <InfoOutlinedIcon sx={{ fontSize: 13 }} />
          </IconButton>
        </Tooltip>
      ) : null}
    </Box>
  );
}

export default function LeadChatHeader({
  conversation,
  userDetail,
  currentUserId = null,
  composerMode = 'idle',
  onClose,
  onToggleSession,
}) {
  const sx = useLeadChatSx();
  const identity = {
    ...userDetail,
    whatsappName: userDetail?.whatsapp_name || conversation?.whatsappName,
    profileName: conversation?.profileName,
    phoneNumber: conversation?.phoneNumber || userDetail?.phone_number,
    leadId: conversation?.leadId,
    last_active_date: userDetail?.last_active_date,
  };
  const displayName = getConversationDisplayName(identity);
  const phone = getConversationPhone(identity);
  const initial = getConversationAvatarInitial(identity);
  const lastSeen = formatLastSeenLabel(identity);
  const defaultSubtitle = phone && displayName !== phone
    ? phone
    : (lastSeen || LEAD_CHAT_COPY.header.statusActive);
  const canStart = canStartLeadChatSession(userDetail, currentUserId);
  const canEnd = canEndLeadChatSession(userDetail, currentUserId);
  const showSessionToggle = canShowSessionToggle(userDetail, currentUserId);
  const lockedByOther = isChatLockedByOtherUser(userDetail, currentUserId);
  const isLiveSession = isComposerActive(composerMode) && canEnd;
  const isViewOnly = isComposerLocked(composerMode) || lockedByOther;

  let subtitleContent = defaultSubtitle;
  if (isLiveSession) {
    subtitleContent = (
      <HeaderStatusLine
        label={LEAD_CHAT_COPY.header.liveSessionStatus}
        tooltip={LEAD_CHAT_COPY.header.liveSessionTooltip}
      />
    );
  } else if (isViewOnly) {
    const agentLabel = getIntervenedAgentLabel(userDetail);
    subtitleContent = (
      <HeaderStatusLine
        label={LEAD_CHAT_COPY.header.handledByCompact(agentLabel)}
        tooltip={LEAD_CHAT_COPY.header.handledByTooltip(agentLabel)}
      />
    );
  }

  return (
    <Box sx={sx.header}>
      <Avatar sx={sx.headerAvatar}>{initial}</Avatar>
      <Box sx={{ flex: 1, minWidth: 0, ml: 1 }}>
        <Typography sx={sx.headerTitle} noWrap>
          {displayName}
        </Typography>
        {typeof subtitleContent === 'string' ? (
          <Typography sx={sx.headerSubtitle} noWrap>
            {subtitleContent}
          </Typography>
        ) : (
          subtitleContent
        )}
      </Box>
      {showSessionToggle ? (
        <Box sx={sx.sessionToggle} role="group" aria-label="Chat session">
          <Button
            color="inherit"
            disableElevation
            onClick={canStart ? onToggleSession : undefined}
            disabled={!canStart}
            aria-pressed={canStart}
            sx={{
              ...sx.sessionToggleOption,
              ...(canStart ? sx.sessionToggleOptionActive : {}),
            }}
          >
            {LEAD_CHAT_COPY.header.startSession}
          </Button>
          <Button
            color="inherit"
            disableElevation
            onClick={canEnd ? onToggleSession : undefined}
            disabled={!canEnd}
            aria-pressed={canEnd}
            sx={{
              ...sx.sessionToggleOption,
              ...(canEnd ? sx.sessionToggleOptionActive : {}),
            }}
          >
            {LEAD_CHAT_COPY.header.endSession}
          </Button>
        </Box>
      ) : null}
      <Tooltip title={LEAD_CHAT_COPY.header.close}>
        <IconButton size="small" onClick={onClose}>
          <CloseIcon sx={{ fontSize: 18 }} />
        </IconButton>
      </Tooltip>
    </Box>
  );
}
