import React, { useEffect, useMemo, useState } from 'react';
import { Box } from '@mui/material';
import SearchableDropdown from '../../../../components/FlowBuilder/Common/SearchableDropdown/SearchableDropdown.tsx';
import { Button, Dialog } from '../../../../components/ui';
import { useSnackBar } from '../../../../components/FlowBuilder/Common/SnackBar/index.tsx';
import { recordService } from '../services/recordService';
import { RECORD_COPY } from '../constants/recordCopy';
import { buildTypeOfStatusList } from '../utils/dynamicFilterUtils';
import {
  buildBulkStatusPayload,
  buildStatusDataFromSelection,
  getStatusFieldDefinitions,
} from '../utils/statusBulkPayload';

export default function BulkStatusModal({
  open,
  onClose,
  tableId,
  formItems,
  selectedRecordIds = [],
  onSuccess,
}) {
  const { showSnackBar } = useSnackBar();
  const [selection, setSelection] = useState({});
  const [statusList, setStatusList] = useState([]);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isLoading, setIsLoading] = useState(false);

  const dynamicFormFields = useMemo(
    () => getStatusFieldDefinitions(formItems),
    [formItems]
  );

  const typeOfStatusList = useMemo(
    () => buildTypeOfStatusList(statusList),
    [statusList]
  );

  useEffect(() => {
    if (!open || !tableId) return undefined;

    let cancelled = false;
    setIsLoading(true);
    setSelection({});

    recordService.fetchStatusList(tableId).then((list) => {
      if (!cancelled) {
        setStatusList(Array.isArray(list) ? list : []);
        setIsLoading(false);
      }
    });

    return () => {
      cancelled = true;
    };
  }, [open, tableId]);

  const handleSubmit = async () => {
    if (!selectedRecordIds.length) {
      showSnackBar('No records selected', 'warning');
      return;
    }

    const statusData = buildStatusDataFromSelection(selection, dynamicFormFields);
    if (!statusData.length) {
      showSnackBar('Please select at least one status', 'warning');
      return;
    }

    setIsSubmitting(true);
    try {
      const payload = buildBulkStatusPayload(
        selectedRecordIds,
        selection,
        dynamicFormFields
      );
      const res = await recordService.bulkUpdateLeadStatus(payload);

      if (res?.status === 200) {
        showSnackBar(RECORD_COPY.success.statusUpdated, 'success');
        onSuccess?.();
        onClose?.();
      } else {
        showSnackBar('Failed to update status', 'error');
      }
    } catch {
      showSnackBar('Failed to update status', 'error');
    } finally {
      setIsSubmitting(false);
    }
  };

  const statusFields = dynamicFormFields.filter(
    (field) => field?.statusOption === 'is_status'
  );
  const subStatusFields = dynamicFormFields.filter(
    (field) => field?.statusOption === 'is_sub_status'
  );

  return (
    <Dialog
      open={open}
      onClose={onClose}
      title={RECORD_COPY.bulk.updateStatus}
      subtitle={RECORD_COPY.bulk.statusSubtitle}
      maxWidth="sm"
      actions={
        <>
          <Button variant="ghost" onClick={onClose} disabled={isSubmitting}>
            {RECORD_COPY.deleteConfirm.cancel}
          </Button>
          <Button
            variant="primary"
            loading={isSubmitting}
            onClick={handleSubmit}
            disabled={isLoading || !dynamicFormFields.length}
          >
            Update
          </Button>
        </>
      }
    >
      {isLoading ? (
        <Box sx={{ py: 2, color: 'text.secondary' }}>Loading status options…</Box>
      ) : !dynamicFormFields.length ? (
        <Box sx={{ py: 2, color: 'text.secondary' }}>
          {RECORD_COPY.bulk.noStatusFields}
        </Box>
      ) : (
        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2, pt: 0.5 }}>
          {statusFields.map((field) => {
            const statusOptions = typeOfStatusList[field.key_name] ?? [];
            const current = selection[field.key_name]?.status ?? null;

            return (
              <SearchableDropdown
                key={field.key_name}
                size="small"
                label={field.alias_name || field.key_name}
                options={statusOptions}
                value={current}
                labelKey="status_name"
                valueKey="status_id"
                onChange={(selected) => {
                  setSelection((prev) => ({
                    ...prev,
                    [field.key_name]: {
                      status: selected,
                      subStatus: null,
                    },
                  }));
                }}
              />
            );
          })}

          {subStatusFields.map((field) => {
            const parentKey = field.status_parent_key;
            const parentStatus = selection[parentKey]?.status ?? null;
            const optionsData = (typeOfStatusList[field.key_name] ?? []).filter(
              (entry) => entry?.status_id === parentStatus?.status_id
            );
            const currentSub = selection[field.key_name]?.subStatus ?? null;

            return (
              <SearchableDropdown
                key={field.key_name}
                size="small"
                label={field.alias_name || field.key_name}
                options={optionsData}
                value={currentSub}
                labelKey="name"
                valueKey="sub_status_id"
                disabled={!parentStatus}
                onChange={(selected) => {
                  setSelection((prev) => ({
                    ...prev,
                    [field.key_name]: {
                      ...prev[field.key_name],
                      subStatus: selected,
                    },
                  }));
                }}
              />
            );
          })}
        </Box>
      )}
    </Dialog>
  );
}
