import React from 'react';
import { Button, Dialog } from '../../../../components/ui';
import { RECORD_COPY } from '../constants/recordCopy';

export default function StatusConfirmDialog({
  open,
  title,
  message,
  isSubmitting = false,
  onConfirm,
  onCancel,
}) {
  return (
    <Dialog
      open={open}
      onClose={onCancel}
      title={title}
      maxWidth="xs"
      showCloseButton={!isSubmitting}
      actions={
        <>
          <Button
            type="button"
            variant="secondary"
            onClick={onCancel}
            disabled={isSubmitting}
          >
            {RECORD_COPY.inlineStatusConfirm.cancel}
          </Button>
          <Button
            type="button"
            variant="primary"
            onClick={onConfirm}
            disabled={isSubmitting}
          >
            {RECORD_COPY.inlineStatusConfirm.confirm}
          </Button>
        </>
      }
    >
      {message}
    </Dialog>
  );
}
