import React from 'react';
import { Alert, Box, LinearProgress, Typography } from '@mui/material';
import { useFeatureTheme } from '../../../../theme/hooks/useFeatureTheme';
import LeadSendTemplateMappingPanel from './LeadSendTemplateMappingPanel';
import LeadSendTemplatePreviewPanel from './LeadSendTemplatePreviewPanel';

export default function LeadSendTemplateIndividualView({
  copy,
  styles,
  template,
  liveBodyParams = [],
  editableFields = [],
  columnOptions = [],
  coverage,
  isSubmitting,
  sendProgress,
  sendSummary,
  onParamChange,
  onColumnSelect,
  stackFields = false,
}) {
  const { semantic, typography } = useFeatureTheme();
  const noValidPhones = coverage?.phoneSummary?.withPhone === 0;

  return (
    <Box sx={styles?.leadSendTemplateSplitBody}>
      <Box sx={styles?.leadSendTemplateSplitGrid}>
        <Box sx={styles?.leadSendTemplateSplitMain}>
          {noValidPhones ? (
            <Alert severity="error" sx={{ mb: 1 }}>
              {copy.direct.noPhoneWarning}
            </Alert>
          ) : null}

          <LeadSendTemplateMappingPanel
            copy={copy}
            styles={styles}
            editableFields={editableFields}
            columnOptions={columnOptions}
            onParamChange={onParamChange}
            onColumnSelect={onColumnSelect}
            stackFields={stackFields}
          />

          {isSubmitting ? (
            <Box sx={{ mt: 1.5 }} aria-live="polite">
              <Typography sx={{ fontSize: typography.fontSizeSm, color: semantic.text.secondary, mb: 0.5 }}>
                {copy.direct.progress(sendProgress.done, sendProgress.total)}
              </Typography>
              <LinearProgress
                variant="determinate"
                value={
                  sendProgress.total
                    ? Math.round((sendProgress.done / sendProgress.total) * 100)
                    : 0
                }
              />
            </Box>
          ) : null}

          {sendSummary ? (
            <Box sx={{ ...styles?.leadSendTemplateSummaryBar, mt: 1.5 }}>
              <Typography component="span" sx={{ color: semantic.text.primary }}>
                {copy.summary(sendSummary.sent, sendSummary.failed, sendSummary.skipped)}
              </Typography>
            </Box>
          ) : null}
        </Box>

        <Box sx={styles?.leadSendTemplateSplitPreview}>
          <LeadSendTemplatePreviewPanel template={template} bodyParams={liveBodyParams} />
        </Box>
      </Box>
    </Box>
  );
}
