import { buildAuthenticatedWsUrl } from '../../../../../shared/sockets';

export function buildLeadChatSocketUrl(botNumber, organisationId = '') {
  const routeToken = botNumber || organisationId;
  if (!routeToken) return null;
  return buildAuthenticatedWsUrl(`/chat/${encodeURIComponent(String(routeToken).trim())}/`);
}

export function buildLeadChatStatusSocketUrl(botNumber, phoneNumber) {
  if (!botNumber || !phoneNumber) return null;
  return buildAuthenticatedWsUrl(`/message-status/${botNumber}/${phoneNumber}/`);
}
