import React from 'react';
import { Box, Typography } from '@mui/material';
import PictureAsPdfOutlinedIcon from '@mui/icons-material/PictureAsPdfOutlined';
import InsertDriveFileOutlinedIcon from '@mui/icons-material/InsertDriveFileOutlined';
import useLeadChatSx from '../../hooks/useLeadChatSx';
import {
  getFileDisplayName,
  getFileExtension,
  getFileTypeLabel,
} from '../../utils/leadChatFileDisplay';

export default function DocumentMessage({ message }) {
  const sx = useLeadChatSx();
  const media = message.media || {};
  const fileName = getFileDisplayName(media.fileName || message.fileName || message.text || 'Document');
  const fileUrl = media.url || message.mediaUrl;
  const extension = getFileExtension(fileName);
  const typeLabel = getFileTypeLabel(fileName);
  const caption = media.caption && media.caption !== fileName ? media.caption : '';
  const showTypeInIcon = extension && extension !== 'document';

  const openFile = () => {
    if (fileUrl) window.open(fileUrl, '_blank', 'noopener,noreferrer');
  };

  return (
    <Box sx={{ width: '100%', maxWidth: 280 }}>
      <Box
        component={fileUrl ? 'button' : 'div'}
        type={fileUrl ? 'button' : undefined}
        onClick={fileUrl ? openFile : undefined}
        sx={{
          ...sx.documentCard,
          width: '100%',
          textAlign: 'left',
          cursor: fileUrl ? 'pointer' : 'default',
          border: sx.documentCard?.border || '1px solid rgba(15, 23, 42, 0.08)',
          font: 'inherit',
          transition: 'background-color 0.15s ease, box-shadow 0.15s ease',
          ...(fileUrl
            ? {
                '&:hover': {
                  bgcolor: 'rgba(18, 140, 126, 0.04)',
                  boxShadow: '0 2px 6px rgba(15, 23, 42, 0.08)',
                },
              }
            : {}),
        }}
        aria-label={`Open ${fileName}`}
      >
        <Box sx={sx.documentIcon}>
          {extension === 'pdf' ? (
            <PictureAsPdfOutlinedIcon sx={{ fontSize: 26 }} />
          ) : showTypeInIcon ? (
            <Typography component="span" sx={sx.documentIconLabel}>
              {typeLabel}
            </Typography>
          ) : (
            <InsertDriveFileOutlinedIcon sx={{ fontSize: 24 }} />
          )}
        </Box>
        <Box sx={{ minWidth: 0, flex: 1 }}>
          <Typography sx={sx.documentTitle} noWrap title={fileName}>
            {fileName}
          </Typography>
          <Typography sx={sx.documentMeta}>
            {fileUrl ? `${typeLabel} · Tap to open` : typeLabel}
          </Typography>
        </Box>
      </Box>
      {caption ? (
        <Box sx={{ mt: 0.75 }}>
          <Typography variant="body2" sx={{ whiteSpace: 'pre-wrap', wordBreak: 'break-word', fontSize: '0.8125rem' }}>
            {caption}
          </Typography>
        </Box>
      ) : null}
    </Box>
  );
}
