import { resolveLeadPhoneFromRow } from '../../utils/leadTemplateSendUtils';

function getLeadId(row) {
  return String(row?.lead_id ?? row?._rawLead?.lead_id ?? '').trim();
}

export function resolveWhatsappProfileName(row) {
  const rawLead = row?._rawLead ?? row;
  const leadId = getLeadId(row);
  const candidates = [
    rawLead?.whatsapp_name,
    rawLead?.name,
    row?.name,
    row?.customer_name,
    rawLead?.customer_name,
  ];

  for (const candidate of candidates) {
    const value = String(candidate ?? '').trim();
    if (!value || (leadId && value === leadId)) continue;
    return value;
  }

  return '';
}

export function resolveWhatsappDisplayName(row, fallback = 'Customer') {
  return resolveWhatsappProfileName(row) || getLeadId(row) || fallback;
}

/** @deprecated Use resolveWhatsappDisplayName */
export function resolveWhatsappName(row) {
  return resolveWhatsappDisplayName(row, '');
}

export function buildLeadChatBaseContext(row, organisationId, leadsFormId) {
  if (!row) return null;

  const phoneResult = resolveLeadPhoneFromRow(row);
  if (!phoneResult.valid) return null;

  return {
    phoneNumber: phoneResult.normalized,
    organisationId: organisationId || '',
    whatsappName: resolveWhatsappDisplayName(row),
    profileName: resolveWhatsappProfileName(row),
    leadId: getLeadId(row),
    rowId: String(row?.id ?? row?.lead_id ?? ''),
    leadsFormId: leadsFormId ?? row?._rawLead?.leads_form_id ?? row?.leads_form_id ?? '',
  };
}

export function buildLeadChatContext(baseContext, botNumber) {
  if (!baseContext || !botNumber) return null;
  return {
    ...baseContext,
    botNumber: String(botNumber),
  };
}

export function getLeadChatKey(phoneNumber, botNumber) {
  if (!phoneNumber || !botNumber) return '';
  return `${phoneNumber}:${botNumber}`;
}
