import { getMessageTimestampMs } from '../../../../intervene/utils/normalizeMessageTimestamp';
import { sanitizeLeadChatFileName } from './leadChatDisplayUtils';

const BUTTON_KEYS = ['buttons', 'button', 'actions', 'action_buttons'];

const TYPE_ALIASES = {
  TEXT: 'text',
  TEMPLATE: 'template',
  IMAGE: 'image',
  VIDEO: 'video',
  AUDIO: 'audio',
  DOCUMENT: 'document',
  FILE: 'document',
  BUTTONS: 'buttons',
  LIST: 'list',
};

const INTERNAL_LIST_PAYLOAD_KEYS = new Set([
  'bot_id',
  'level',
  'flow_id',
  'node',
  'entity_id',
  'result_key',
  'result_name',
]);

function get(obj, path, fallback = undefined) {
  if (!obj) return fallback;
  const value = path.split('.').reduce((acc, key) => (acc == null ? undefined : acc[key]), obj);
  return value === undefined ? fallback : value;
}

function toArray(value) {
  if (Array.isArray(value)) return value;
  if (!value) return [];
  return [value];
}

function compact(values) {
  return values.filter((value) => value !== undefined && value !== null && value !== '');
}

function firstText(...values) {
  return compact(values).find((value) => typeof value === 'string' && value.trim()) || '';
}

function asText(block) {
  if (typeof block === 'string') return block;
  if (block && typeof block === 'object') return block.text || '';
  return '';
}

function normalizeRawType(rawType) {
  if (!rawType || typeof rawType !== 'string') return 'text';
  return TYPE_ALIASES[rawType.toUpperCase()] || rawType.toLowerCase();
}

function normalizeStatus(message) {
  const status = message?.status?.type || message?.status || message?.message_status;
  if (!status) return null;
  if (typeof status === 'string') return status.toLowerCase();
  if (typeof status === 'object') return (status.type || status.status || '').toLowerCase();
  return `${status}`.toLowerCase();
}

function extractMessageText(message) {
  return firstText(
    get(message, 'content.body.text'),
    typeof message?.content?.body === 'string' ? message.content.body : null,
    get(message, 'content.text'),
    get(message, 'body.text'),
    message?.text,
    message?.message,
    get(message, 'interactive.body.text'),
    get(message, 'template.body.text')
  );
}

function extractFooter(message) {
  return firstText(
    get(message, 'content.footer.text'),
    typeof message?.content?.footer === 'string' ? message.content.footer : null,
    get(message, 'interactive.footer.text'),
    get(message, 'template.footer.text'),
    message?.footer
  );
}

function extractHeader(message) {
  const header = message?.content?.header || message?.header;
  if (header && typeof header === 'object') {
    const headerType = (header.type || header.format || 'TEXT').toUpperCase();
    switch (headerType) {
      case 'IMAGE':
      case 'PHOTO':
        return {
          kind: 'image',
          url: firstText(header.link, header.url, header.image?.link, header.image?.url),
          text: null,
          fileName: null,
        };
      case 'VIDEO':
        return {
          kind: 'video',
          url: firstText(header.link, header.url, header.video?.link, header.video?.url),
          text: null,
          fileName: null,
        };
      case 'DOCUMENT':
      case 'FILE':
      case 'PDF':
        return {
          kind: 'document',
          url: firstText(
            header.link,
            header.url,
            header.document?.link,
            header.document?.url,
            header.file?.link,
            header.file?.url
          ),
          text: null,
          fileName: sanitizeLeadChatFileName(
            firstText(
              header.filename,
              header.file_name,
              header.caption,
              header.name,
              header.document?.filename,
              header.document?.name,
              header.file?.filename
            )
          ),
        };
      case 'TEXT':
        return { kind: 'text', text: header.text || '', url: null, fileName: null };
      default:
        if (header.text) return { kind: 'text', text: header.text, url: null, fileName: null };
        if (header.link || header.url) {
          return {
            kind: 'document',
            url: firstText(header.link, header.url),
            text: null,
            fileName: sanitizeLeadChatFileName(
              firstText(header.filename, header.file_name, header.caption, header.name)
            ),
          };
        }
        break;
    }
  }

  const textHeader = firstText(
    typeof header === 'string' ? header : null,
    get(message, 'interactive.header.text'),
    get(message, 'template.header.text'),
    message?.title
  );

  if (textHeader) {
    return { kind: 'text', text: textHeader, url: null, fileName: null };
  }

  return null;
}

function extractButtonLike(entry) {
  if (!entry) return null;
  const label = firstText(
    entry?.label,
    entry?.text,
    entry?.title,
    entry?.reply?.title,
    entry?.button_text,
    entry?.name
  );
  if (!label) return null;

  return {
    id: firstText(entry?.id, entry?.reply?.id, entry?.payload, entry?.value),
    label,
    type: firstText(entry?.type, entry?.reply?.type, entry?.sub_type),
    url: firstText(entry?.url, entry?.href, entry?.value),
  };
}

function extractButtons(message) {
  for (const key of BUTTON_KEYS) {
    const sources = [
      message?.[key],
      message?.content?.[key],
      message?.interactive?.[key],
      message?.body?.[key],
    ];

    for (const source of sources) {
      const buttons = toArray(source).map(extractButtonLike).filter(Boolean);
      if (buttons.length) return buttons;
    }
  }

  const componentButtons = toArray(message?.template?.components)
    .filter((component) => component?.type === 'BUTTONS')
    .flatMap((component) => toArray(component?.buttons).map(extractButtonLike).filter(Boolean));
  if (componentButtons.length) return componentButtons;

  const contentComponentButtons = toArray(message?.content?.components)
    .filter((component) => component?.type === 'BUTTONS')
    .flatMap((component) => toArray(component?.buttons).map(extractButtonLike).filter(Boolean));
  if (contentComponentButtons.length) return contentComponentButtons;

  const interactiveActionButtons = toArray(message?.interactive?.action?.buttons)
    .map(extractButtonLike)
    .filter(Boolean);
  if (interactiveActionButtons.length) return interactiveActionButtons;

  const templateButtons = toArray(message?.content?.buttons).map(extractButtonLike).filter(Boolean);
  if (templateButtons.length) return templateButtons;

  return [];
}

function parseJsonObject(value) {
  if (typeof value !== 'string') return null;
  const trimmed = value.trim();
  if (!trimmed.startsWith('{') && !trimmed.startsWith('[')) return null;

  try {
    const parsed = JSON.parse(trimmed);
    return parsed && typeof parsed === 'object' ? parsed : null;
  } catch {
    return null;
  }
}

function isInternalListPayload(value) {
  const parsed = parseJsonObject(value);
  if (!parsed || Array.isArray(parsed)) return false;
  return Object.keys(parsed).some((key) => INTERNAL_LIST_PAYLOAD_KEYS.has(key));
}

function pickListDisplayText(...values) {
  for (const value of compact(values)) {
    if (typeof value !== 'string') continue;
    const trimmed = value.trim();
    if (!trimmed || isInternalListPayload(trimmed)) continue;
    return trimmed;
  }
  return '';
}

function normalizeListOption(rawOption = {}) {
  const title = pickListDisplayText(rawOption?.title, rawOption?.label, rawOption?.name, rawOption?.text);
  const description = pickListDisplayText(
    rawOption?.description,
    rawOption?.subtitle,
    rawOption?.postbackText,
    rawOption?.body
  );

  return {
    id: firstText(rawOption?.id, rawOption?.value, rawOption?.payload) || null,
    title,
    ...(description ? { description } : {}),
  };
}

function extractListItems(message) {
  const items = toArray(message?.content?.list || message?.content?.items);
  if (items.length) {
    const listTitle = firstText(items[0]?.title, items[0]?.name) || 'Options';
    const options = items
      .flatMap((item) => toArray(item?.options).map(normalizeListOption))
      .filter((option) => option.title);

    if (options.length) {
      return { listTitle, options };
    }
  }

  const sectionSources = [
    message?.interactive?.action?.sections,
    message?.content?.sections,
    message?.content?.rows,
  ];

  for (const sections of sectionSources) {
    const normalizedSections = toArray(sections)
      .flatMap((section) =>
        toArray(section?.rows || section?.items || section?.options).map(normalizeListOption)
      )
      .filter((row) => row.title);

    if (normalizedSections.length) {
      return {
        listTitle: firstText(toArray(sections)[0]?.title) || 'Options',
        options: normalizedSections,
      };
    }
  }

  return { listTitle: 'Options', options: [] };
}

function stringifyTemplateParam(value) {
  if (value == null) return '';
  if (typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') {
    return String(value);
  }
  if (value.text) return String(value.text);
  if (value.value) return String(value.value);
  return JSON.stringify(value);
}

function flattenTemplateParams(parameters) {
  if (!parameters) return [];
  if (Array.isArray(parameters)) return parameters.map(stringifyTemplateParam);
  const values = [];
  Object.values(parameters).forEach((entry) => {
    if (Array.isArray(entry)) entry.forEach((item) => values.push(stringifyTemplateParam(item)));
    else values.push(stringifyTemplateParam(entry));
  });
  return values;
}

function fillTemplatePlaceholders(text, parameters) {
  if (!text) return '';
  const values = flattenTemplateParams(parameters);
  return text.replace(/{{\s*(\d+)\s*}}/g, (_match, indexStr) => {
    const index = parseInt(indexStr, 10) - 1;
    const replacement = values[index];
    return replacement?.length ? replacement : `{{${indexStr}}}`;
  });
}

function extractTemplate(message) {
  const content = message?.content || {};
  const bodyBlock = content.body;
  let bodyText = '';
  let parameters = [];

  if (typeof bodyBlock === 'string') {
    bodyText = bodyBlock;
  } else if (bodyBlock) {
    bodyText = bodyBlock.text || '';
    parameters = bodyBlock.parameters;
  }

  const headerText = asText(content.header);
  const footerText = asText(content.footer);
  const resolvedBody = fillTemplatePlaceholders(bodyText, parameters);

  return {
    name: firstText(content.template_name, content.name, message?.template_name) || null,
    header: headerText || null,
    body: resolvedBody || bodyText || null,
    footer: footerText || null,
    buttons: extractButtons(message),
  };
}

function extractMediaUrl(message) {
  const content = message?.content || {};
  return firstText(
    get(content, 'media.s3_object.url'),
    get(content, 'media.url'),
    content.previewUrl,
    content.url,
    message?.url,
    get(content, 'header.link'),
    get(content, 'header.url'),
    get(content, 'image.link'),
    get(content, 'image.url'),
    get(content, 'video.link'),
    get(content, 'video.url'),
    get(content, 'document.link'),
    get(content, 'document.url'),
    get(content, 'audio.link'),
    get(content, 'audio.url'),
    get(message, 'document.url'),
    get(message, 'image.url'),
    get(message, 'video.url'),
    get(message, 'audio.url'),
    message?.media_url
  );
}

function extractFileName(message) {
  const content = message?.content || {};
  return firstText(
    content.filename,
    content.file_name,
    content.name,
    get(content, 'document.filename'),
    get(content, 'document.name'),
    get(content, 'media.filename'),
    get(message, 'document.filename'),
    get(message, 'document.name')
  );
}

function detectKind(message, rawType, listItems, buttons) {
  const type = normalizeRawType(rawType);

  if (type === 'template') return 'template';
  if (type === 'buttons') return 'buttons';
  if (type === 'list') return 'list';
  if (type === 'image' || type === 'video' || type === 'audio' || type === 'document') {
    return type;
  }

  if (listItems.options.length) return 'list';
  if (buttons.length && (type === 'buttons' || rawType === 'BUTTONS')) return 'buttons';

  const mediaMime = firstText(message?.content?.mime_type, message?.mime_type, message?.file_type);
  if (mediaMime.startsWith('image/')) return 'image';
  if (mediaMime.startsWith('audio/')) return 'audio';
  if (mediaMime.startsWith('video/')) return 'video';
  if (mediaMime.includes('pdf') || mediaMime.includes('document')) return 'document';

  if (
    type === 'template'
    || (message?.content?.template_name && type !== 'text')
    || message?.template
    || message?.content?.template
  ) {
    return 'template';
  }

  return type || 'text';
}

const EMPTY_NORMALIZED = {
  kind: 'text',
  text: '',
  timestamp: null,
  status: null,
  isMine: false,
  mediaUrl: '',
  fileName: '',
  media: null,
  header: null,
  footer: null,
  buttons: [],
  template: null,
  listTitle: 'Options',
  listOptions: [],
  templateName: '',
  raw: null,
};

export function normalizeLeadChatMessage(message) {
  if (!message) {
    return { ...EMPTY_NORMALIZED };
  }

  const rawType = firstText(
    message?.content?.type,
    message?.content?.body?.type,
    message?.type,
    message?.message_type,
    message?.interactive?.type
  ) || 'text';

  const buttons = extractButtons(message);
  const listItems = extractListItems(message);
  const kind = detectKind(message, rawType, listItems, buttons);
  const text = extractMessageText(message);
  const header = extractHeader(message);
  const footer = extractFooter(message);
  const template = kind === 'template' ? extractTemplate(message) : null;
  const mediaUrl = extractMediaUrl(message);
  const fileName = extractFileName(message);
  const mediaKind = kind === 'image' || kind === 'video' || kind === 'audio' || kind === 'document'
    ? kind
    : null;

  const timestamp = getMessageTimestampMs(message);
  const origin = `${message?.origin || ''}`.toUpperCase();
  const isMine = origin === 'OUTBOUND';
  const templateName = firstText(
    message?.template_name,
    message?.content?.template_name,
    template?.name
  );

  return {
    kind,
    text: template?.body || text,
    timestamp,
    status: normalizeStatus(message),
    isMine,
    mediaUrl,
    fileName,
    media: mediaKind
      ? {
          kind: mediaKind,
          url: mediaUrl || null,
          fileName: fileName || null,
          caption: text || null,
        }
      : null,
    header,
    footer: footer || template?.footer || null,
    buttons: buttons.length ? buttons : (template?.buttons || []),
    template,
    listTitle: listItems.listTitle,
    listOptions: listItems.options,
    templateName,
    raw: message,
  };
}

export function getMessageKey(message, index) {
  const id = message?.msg_id || message?.w_id || message?.id || message?.message_id;
  return id ? String(id) : `idx-${index}`;
}
